30	    /**
31	     * Determine an owner's membership tier: {@code "SILVER"} when the owner has no namesakes
32	     * (its {@code namesakeCount} is {@code 0}) and an email address is present, otherwise
33	     * {@code "BRONZE"}. A null or absent namesake count is treated as not being zero, so the
34	     * tier only reaches SILVER for an explicitly unique owner with an email.
35	     */
36	    default String formatMembershipTier(Owner owner) {
37	        if (owner == null) {
38	            return null;
39	        }
40	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
41	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
42	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
43	    }
44	
45	    /**
46	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
47	     * is the last two digits of the registration date year (e.g. {@code "SMI-0007-M26"}).
48	     * Returns {@code null} when either the customer code or registration date is absent, since
49	     * the number cannot be derived without both.
50	     */
51	    default String formatMembershipNumber(Owner owner) {
52	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
53	            return null;
54	        }
55	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
56	    }
