59	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
60	     */
61	    default String formatDisplayName(Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        return owner.getLastName() + ", " + owner.getFirstName();
66	    }
