68	    /**
69	     * Format an owner's initials as the upper-cased first letters of the first and last
70	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
71	     */
72	    default String formatInitials(Owner owner) {
73	        if (owner == null) {
74	            return null;
75	        }
76	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
77	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
